insert into exercises(id, team_id, place, phase, name, page, data) values
  ('ex01', null, 'grass', 'auf', 'Freies Kleinfeldspiel', '60', '{"org":"Zwei Kleinfelder ca. 25×15 m mit je zwei Minitoren, aufgebaut bevor das erste Kind kommt.","ablauf":"Wer ankommt, spielt sofort frei, vom 1:0 bis zum 4:4. Sind acht Kinder auf einem Feld, schickst du die nächsten ins zweite Feld.","coach":["Laufen lassen, noch nicht korrigieren","Ankommende Kinder kurz begrüssen"],"var":"Spielfeldgrösse der Anzahl Kinder anpassen.","d":{"s":"grass","items":[["area",6,3,88,27],["area",6,34,88,27],["m",6,16],["m",94,16,1],["m",6,47],["m",94,47,1],["A",34,12],["A",40,22,1],["B",58,14],["B",62,24],["A",30,44,1],["B",52,52],["drib",42,22,58,20],["shot",60,19,92,16],["shot",32,44,8,47]]}}'::jsonb),
  ('ex02', null, 'grass', 'ein', 'Schatzinsel', '61', '{"org":"Feld 25×25 m, Insel in der Mitte, zwei Piratenschiffe in den Ecken. Jedes Kind mit Ball.","offen":"Bei «Ahoi, Piraten!» dribbeln alle zur Insel. Bei «Hejo, Captain Jack!» Ball liegen lassen und mit einem freien Ball weiterdribbeln.","ueben":"Nur links, nur rechts, abwechselnd; nur mit Voll-, Innen- oder Aussenrist führen.","wett":"Piraten gegen Affen: Die Affen beschützen die Bälle auf der Insel, die Piraten entführen sie dribbelnd aufs Schiff. Affen dürfen Bälle zurückholen. Wer hat nach zwei Minuten mehr Bälle?","coach":["Heutiger Fokus liegt im Wetteifern: wie eine Wespe den Ball jagen (S. 42)","Nach dem Ballgewinn den Körper als Schutzschild einsetzen"],"var":"Mehr Affen macht es für die Piraten schwerer, eine grössere Insel leichter.","d":{"s":"grass","items":[["area",14,4,72,56],["zone",40,22,20,20,"Insel"],["zone",14,4,16,12,"Schiff"],["zone",70,48,16,12,"Schiff"],["B",45,28],["B",55,36],["ball",47,35],["ball",53,27],["ball",50,31],["A",32,22,1],["A",68,40,1],["A",28,44],["A",72,18],["drib",34,23,24,12],["drib",70,41,77,52],["run",55,36,66,42],["run",28,44,42,36]]}}'::jsonb),
  ('ex03', null, 'grass', 'sp', 'Kleinfeldspiel 3:3 – Ab auf die andere Seite', '81 · 71', '{"org":"Zwei Felder 30×20 m mit Endzone an beiden Enden und je einem Minitor. 3:3 und 4:4.","offen":"Tore zählen nur aus der Endzone. Das Team, das trifft, bleibt im Ballbesitz und greift sofort in die andere Richtung an.","ueben":"Nach dem Tor sofort auf die neue Situation umschalten und den freien Raum nutzen.","wett":"Welchem Team gelingen zwei Tore in Folge?","coach":["Bei Ballgewinn die Blume öffnen, bei Ballverlust schliessen (S. 42)","Bei Fouls entscheiden die Kapitäne (S. 81)"],"var":"Tiefere Endzone erleichtert den Abschluss.","d":{"s":"grass","items":[["zone",0,0,14,64,"Endzone"],["zone",86,0,14,64,"Endzone"],["m",0,32],["m",100,32,1],["A",30,20],["A",46,44],["A",62,30],["B",72,18],["B",76,46],["B",40,32],["drib",62,32,88,36],["shot",90,36,99,33],["drib",90,40,60,52],["txt",50,62,"Nach dem Tor sofort zurück angreifen"]]}}'::jsonb),
  ('ex04', null, 'grass', 'le', '1:1 mit Umschalten', '68', '{"org":"Zwei Stationen à 7 Kinder: grosses Tor mit Torhüter/in, Schusszone vor dem Tor, Startreihe ca. 25 m entfernt.","offen":"Ein Kind dribbelt Richtung Schusszone und versucht im 1:1 ein Tor zu erzielen. Nach dem Abschluss verteidigt es selbst, das nächste Kind startet sofort.","ueben":"Situation sofort wahrnehmen, mit Tempo und Richtungswechseln zum Tor; danach rasch die Verteidigerrolle einnehmen.","wett":"Zwei Teams: Welches erzielt mehr Tore? Nach einem Durchgang die Seiten wechseln.","coach":["Vor dem Tor entschlossen wie eine Raubkatze (S. 75)","Vor dem Schiessen ein Foto vom Tor machen","Als Verteidiger/in wie eine Wespe den Ball jagen"],"var":"Schusszone näher am Start macht es leichter, ein früherer Start des Verteidigers schwerer.","d":{"s":"grass","items":[["zone",70,12,18,40,"Schusszone"],["G","R"],["B",97,32],["A",8,28],["A",8,36],["A",4,32],["A",22,32,1],["B",80,44],["drib",24,32,66,31],["run",80,44,70,36],["shot",72,30,98,28],["txt",12,46,"Startreihe"]]}}'::jsonb),
  ('ex05', null, 'grass', 'vi', 'Jäger und Hase', '80', '{"org":"Paare. Jagdzone ca. 10×10 m, am Ende ein rotes und ein gelbes Tor aus Hütchen.","offen":"Auf ein Signal startet der Hase in die Jagdzone, gleichzeitig rennt der Jäger los. Je nach Jäger sprintet der Hase durchs rote oder gelbe Tor, der Jäger versucht ihn zu berühren. Dann Rollen tauschen.","ueben":"Mit einer überraschenden Körpertäuschung den Jäger überlisten.","wett":"Welcher Hase sammelt die meisten Punkte? Welcher Jäger schlägt fünf Hasen?","coach":["Täuschen und schlau sein wie ein Fuchs"],"var":"Breitere Jagdzone erleichtert es dem Hasen.","d":{"s":"grass","items":[["area",28,8,40,48],["c",68,12],["c",68,24],["c",68,40],["c",68,52],["txt",76,19,"rot"],["txt",77,47,"gelb"],["A",22,32],["B",48,4],["run",24,32,48,34],["run",48,34,67,46],["run",48,6,58,38]]}}'::jsonb),
  ('ex06', null, 'grass', 'sp', 'Der Match – Grossfeld', '81', '{"org":"Grossfeld mit zwei grossen Toren, maximal 6:6 inkl. Torhüter/in. Bei 14 Kindern rotieren zwei Kinder auf dein Signal ein, alle spielen gleich lang.","ablauf":"Die Kinder bilden selbst ausgeglichene Teams, bestimmen Kapitäne, machen eine Grundordnung und starten das Spiel selbstständig.","coach":["Erobern wie eine Wespe, abschliessen wie eine Raubkatze","Shakehands nach dem Schlusspfiff"],"var":"","d":{"s":"grass","full":1,"items":[["G","L"],["G","R"],["A",3,32],["A",22,18],["A",22,46],["A",40,32],["A",58,20,1],["A",60,44],["B",97,32],["B",78,18],["B",78,46],["B",64,30],["B",46,48],["B",44,16],["run",64,30,60,24],["drib",60,20,74,22],["shot",76,23,98,29]]}}'::jsonb),
  ('ex07', null, 'grass', 'aus', 'Penalty-König/in', '82', '{"org":"Ein grosses Tor, Torhüter/in wechselt.","ablauf":"Abwechselnd Penaltys, jedes Tor ein Punkt. 1. Durchgang links, 2. Durchgang rechts, 3. Durchgang freie Wahl. Wer hat nach drei Durchgängen am meisten Tore? Danach Schlusswort und persönliche Verabschiedung.","coach":["Alle bleiben dabei, niemand scheidet aus (S. 52)"],"var":"","d":{"s":"grass","items":[["zone",80,16,20,32,""],["G","R"],["B",97,32],["ball",88,32],["A",70,32],["A",66,28],["A",66,36],["A",62,32],["run",72,32,86,32],["shot",88,32,98,28]]}}'::jsonb),
  ('ex08', null, 'grass', 'auf', 'Kickstart', '60', '{"org":"Mindestens sechs Minitore stehen bereit.","ablauf":"Wer ankommt, nimmt einen Ball und schiesst auf verschiedene Tore oder absolviert selbstständig einen Torschussrundlauf.","coach":["Vor dem Schuss ein Foto vom Tor machen"],"var":"Distanz zu den Toren verändern.","d":{"s":"grass","items":[["m",10,12],["m",10,32],["m",10,52],["m",90,12,1],["m",90,32,1],["m",90,52,1],["A",40,20,1],["A",58,40,1],["A",46,48,1],["B",60,18],["shot",42,20,88,13],["shot",57,41,12,51],["drib",48,48,62,52]]}}'::jsonb),
  ('ex09', null, 'grass', 'ein', 'Passduell', '62', '{"org":"Inneres Feld ca. 15×15 m für Tandems, aussen herum ein Dribbel-Parcours. Zwei Teams à 7.","offen":"Ein Team dribbelt aussen durch den Parcours, das andere passt sich im inneren Feld in Tandems die Bälle zu. Danach wechseln.","ueben":"Annehmen, vorlegen, zuspielen (drei Kontakte); Distanz variieren; nur links, nur rechts.","wett":"Wie viele Pässe schaffen die Tandems, bis alle Kinder den Parcours absolviert haben?","coach":["Fuss als Golfschläger: fest anspannen und ausdrehen (S. 70)","Vor dem Pass ein Foto vom Ziel machen"],"var":"Distanz zwischen den Tandems verändern.","d":{"s":"grass","items":[["area",34,16,32,32],["c",18,8],["c",40,6],["c",60,8],["c",82,6],["c",88,32],["c",82,58],["c",60,56],["c",40,58],["c",18,56],["c",12,32],["A",40,24],["A",58,24,1],["A",42,40,1],["A",60,42],["pass",56,24,42,24],["pass",44,40,58,41],["B",28,8,1],["B",88,20,1],["B",50,58,1],["drib",30,8,48,8],["drib",88,22,88,44]]}}'::jsonb),
  ('ex10', null, 'grass', 'sp', 'Kleinfeldspiel 3:3 – Torspieler/in in der Abschlusszone', '81 · 76', '{"org":"Zwei Felder 30×20 m, an jeder Stirnseite zwei Minitore in den Ecken mit Abschlusszone davor. 3:3 plus je ein/e Torspieler/in, Torspieler/in wechselt nach jedem Gegentor.","offen":"Die Torspieler/innen dürfen den Ball in der Abschlusszone mit den Händen abwehren.","ueben":"Mit rascher Spielverlagerung die Breite nutzen und aufs freie Tor abschliessen. Als Torspieler/in rasch verschieben.","wett":"Welche/r Torspieler/in bekommt am wenigsten Tore?","coach":["Blume öffnen: breit stehen, damit das freie Tor aufgeht"],"var":"Breiteres Feld gibt mehr Raum für die Verlagerung.","d":{"s":"grass","items":[["zone",0,0,12,64,"Zone"],["zone",88,0,12,64,"Zone"],["m",0,12],["m",0,52],["m",100,12,1],["m",100,52,1],["A",6,32],["B",94,48],["A",48,48,1],["A",64,14],["A",36,24],["B",70,44],["B",56,36],["B",40,40],["pass",50,47,63,16],["shot",66,14,99,12],["txt",50,62,"Verlagern auf das freie Tor"]]}}'::jsonb),
  ('ex11', null, 'grass', 'le', 'Angreifen in Überzahl – 3:1', '72', '{"org":"Zwei Felder 30×20 m mit Mittellinie und zwei Minitoren an der Stirnseite. Pro Feld drei Angreifer/innen und ein/e Verteidiger/in, Rollen rotieren.","offen":"Team Weiss greift im 3:1 (oder 2:1) auf die beiden Tore an. Geschossen wird ab der Mittellinie. Ist der Ball im Tor oder im Aus, ist der Angriff zu Ende.","ueben":"Mit Zusammenspiel oder Dribbling die Verteidigung ausspielen und entschlossen den Abschluss suchen.","wett":"Schafft das angreifende Team aus acht Versuchen vier Tore?","coach":["Breite und Tiefe: Anspielstationen vorne, hinten und seitlich (Rhombus, Dreieck) (S. 42)","Aus dem Schatten in die Sonne laufen"],"var":"Leichter: 3:0 mit 5–10 Sekunden Zeit. Schwerer: 3:2 (beide S. 72). Stellschraube «Anzahl Spieler».","d":{"s":"grass","items":[["line",50],["m",100,18,1],["m",100,46,1],["A",36,10],["A",36,32,1],["A",36,54],["B",72,32],["run",36,10,66,12],["pass",38,32,64,13],["run",36,54,66,52],["shot",68,13,98,18],["txt",50,62,"Schuss ab der Mittellinie"]]}}'::jsonb),
  ('ex12', null, 'grass', 'vi', 'Hüpfen rund um die Welt', '80', '{"org":"Markiertes Feld mit farbigen Reifen.","offen":"Frei im Feld bewegen und immer wieder ein- und beidbeinig in die Reifen hüpfen, zuerst allein, dann zu zweit: Eines hüpft vor, das andere nach.","ueben":"Reifen nicht berühren und auf dem Vorderfuss springen wie eine Gazelle.","wett":"Wer schafft es ohne Fehler? Stafette mit gleicher Hüpfabfolge oder eigene Abfolgen erfinden lassen.","coach":["Leicht und federnd landen"],"var":"Reifen weiter auseinander legen macht es schwerer.","d":{"s":"grass","items":[["area",14,6,72,52],["hoop",28,18],["hoop",40,26],["hoop",52,16],["hoop",64,28],["hoop",72,44],["hoop",56,46],["hoop",36,44],["hoop",24,34],["A",20,22],["A",48,36],["B",62,54],["run",22,22,38,25],["run",48,36,55,44]]}}'::jsonb),
  ('ex13', null, 'grass', 'aus', 'Linienschiessen', '82', '{"org":"Ein grosses Tor, Markierungen in steigender Distanz.","ablauf":"Aus einer Distanz den Ball in der Luft ins Tor schiessen. Wer trifft, geht zur nächsten, weiter entfernten Markierung, wer nicht trifft, bleibt. Wer trifft wie oft? Danach Schlusswort und Verabschiedung.","coach":["Fragen an die Kinder stellen (siehe oben)"],"var":"","d":{"s":"grass","items":[["G","R"],["c",82,14],["c",82,50],["c",72,14],["c",72,50],["c",62,14],["c",62,50],["A",82,30],["A",72,36],["A",62,26],["shot",83,30,98,31],["shot",73,36,98,34]]}}'::jsonb),
  ('ex14', null, 'hall', 'auf', 'Fangis', '60', '{"org":"Ein Fangisfeld steht bereit.","ablauf":"Wer kommt, spielt selbstständig ein Fangis nach Wahl. Jedes Kind darf einmal Fänger/in sein.","coach":["Ältere Kinder toben sich gern in Fang- und Laufspielen aus (S. 37)"],"var":"Feldgrösse an die Anzahl Kinder anpassen.","d":{"s":"hall","items":[["area",14,6,72,52],["B",48,30],["A",30,18],["A",66,20],["A",34,44],["A",64,46],["run",48,30,36,42],["run",34,44,22,52]]}}'::jsonb),
  ('ex15', null, 'hall', 'ein', 'Spiel mit dem Feuer', '64', '{"org":"Halbe Halle, jedes Kind mit Ball. Zwei Kinder sind das «Feuer» (Überzieher).","offen":"Die Feuer versuchen, dribbelnde Kinder zu berühren. Wer sich verbrennt, erfüllt eine Aufgabe oder umdribbelt das Spielfeld.","ueben":"Dribbling mit beiden Füssen, Innen- und Aussenfuss; Finten wie Körpertäuschung, Übersteiger oder Schere.","wett":"Welches Feuer erwischt in einer Minute am meisten Kinder?","coach":["Den Ball als Hund bei Fuss halten (S. 42)","Mit Finten ausweichen, schlau wie ein Fuchs"],"var":"Mehr Feuer machen es schwerer.","d":{"s":"hall","items":[["area",10,6,80,52],["B",46,26],["B",62,40],["A",24,18,1],["A",70,16,1],["A",30,44,1],["A",54,50,1],["A",76,34,1],["A",40,34,1],["run",46,26,40,32],["drib",40,34,28,38],["run",62,40,54,48]]}}'::jsonb),
  ('ex16', null, 'hall', 'sp', 'Kleinfeldspiel 3:3', '81', '{"org":"Halle quer in zwei Kleinfelder teilen, je zwei Minitore oder umgekippte Langbänke. 3:3 und 4:4.","ablauf":"Freies Spiel. Die Kinder bilden die Teams selbst und lösen Fouls über die Kapitäne.","own":"Eigene Zusatzregel (nicht im Manual): Ein Tor direkt nach Ballgewinn zählt doppelt.","coach":["Nach Ballverlust sofort jagen wie eine Wespe","Nach Ballgewinn Blume öffnen"],"var":"Kleineres Feld bringt mehr Duelle.","d":{"s":"hall","items":[["line",50],["m",0,32],["m",50,32,1],["m",50,32],["m",100,32,1],["A",14,22],["A",22,42,1],["A",34,30],["B",40,20],["B",36,44],["B",28,30],["run",28,30,22,40],["A",64,24],["A",72,42],["A",80,30],["B",86,20],["B",88,44],["B",70,32,1],["drib",70,34,92,34],["shot",93,34,99,32]]}}'::jsonb),
  ('ex17', null, 'hall', 'le', '1:1 mit acht Toren', '69', '{"org":"Zwei parallele Bahnen ca. 20×12 m, an jedem Ende zwei Minitore mit Abschlusszone (acht Tore). Team Rot und Team Weiss stehen sich gegenüber.","offen":"Zwei Kinder von Rot dribbeln gleichzeitig ins Feld und passen auf die andere Seite zur Gegenspielerin oder zum Gegenspieler. Danach folgt das 1:1 auf die beiden Minitore. Erobert Rot den Ball zurück, kontert es auf die gegenüberliegenden Minitore. Tore zählen nur aus der Abschlusszone.","ueben":"Nach erfolgreicher Ballkontrolle schnell Richtung Minitore dribbeln, mit Richtungswechsel oder gut getimter Finte austricksen und abschliessen.","wett":"Jedes Kind hat drei Versuche. Wer erzielt mehr Tore?","coach":["Verteidigen wie eine Wespe, nach Ballgewinn sofort kontern","Vor dem Tor entschlossen wie eine Raubkatze"],"var":"Schmalere Bahn macht es für den Angreifer schwerer.","d":{"s":"hall","items":[["area",4,3,92,26],["area",4,35,92,26],["zone",4,3,12,26,""],["zone",84,3,12,26,""],["zone",4,35,12,26,""],["zone",84,35,12,26,""],["m",4,9],["m",4,23],["m",96,9,1],["m",96,23,1],["m",4,41],["m",4,55],["m",96,41,1],["m",96,55,1],["A",24,12],["B",78,12],["pass",26,12,76,12],["drib",78,18,30,22],["run",26,14,36,20],["A",40,48,1],["B",34,54],["drib",42,48,80,46],["shot",82,46,95,42],["txt",60,58,"Ballgewinn = Konter"]]}}'::jsonb),
  ('ex18', null, 'hall', 'vi', 'Feuerball (Tupfball)', '80', '{"org":"Vierecke ca. 8×8 m. Pro Viereck ein Dreierteam und ein «Eisbär» des anderen Teams.","offen":"Das Dreierteam spielt sich den Ball mit den Händen zu und versucht, den Eisbären mit dem Ball zu berühren, nicht abzuschiessen. Mit dem Ball in der Hand darf man nicht laufen.","ueben":"Mit raschem Zusammenspiel den Eisbären in die Ecke drängen.","wett":"Welches Team erzielt mehr Punkte? Welcher Eisbär kann sich freilaufen?","coach":["Gemeinsam im Schwarm jagen, wie beim Erobern im Fussball"],"var":"Grösseres Viereck erleichtert es dem Eisbären.","d":{"s":"hall","items":[["area",8,8,36,48],["area",56,8,36,48],["A",12,12,1],["A",40,22],["A",18,50],["B",28,34],["pass",14,14,38,21],["A",60,14],["A",88,20,1],["A",66,52],["B",76,36],["pass",86,22,77,34]]}}'::jsonb),
