  ('ex20', null, 'hall', 'aus', 'Schiessbude', '82', '{"org":"Mit dem gesamten Trainingsmaterial baust du im Tor eine Schiessbude auf.","ablauf":"Wer trifft am meisten Gegenstände? Danach Schlusswort, Verabschiedung und gemeinsamer Abbau.","coach":["Alle helfen beim Auf- und Abbau (S. 52)"],"var":"","d":{"s":"hall","items":[["G","R"],["c",97,28],["c",97,32],["c",97,36],["box",92,24,3,3,""],["box",92,37,3,3,""],["A",70,22,1],["A",68,32,1],["A",70,42,1],["shot",72,22,96,27],["shot",70,32,96,32]]}}'::jsonb),
  ('ex21', null, 'hall', 'auf', 'Dribblestart', '60', '{"org":"Ein Feld mit unterschiedlichen Gegenständen steht bereit (Kegel, Reifen, Langbank, Kastenteil).","ablauf":"Wer kommt, schnappt sich einen Ball und umdribbelt die Gegenstände.","coach":["Wer früh da ist, hilft beim Aufbau"],"var":"Gegenstände enger stellen macht es schwerer.","d":{"s":"hall","items":[["c",22,14],["c",40,46],["c",70,18],["hoop",54,30],["hoop",28,40],["bench",60,48,22,4,"Langbank"],["box",80,26,8,10,"Kasten"],["A",34,24,1],["A",62,30,1],["A",48,52,1],["drib",36,24,24,18],["drib",62,32,76,30]]}}'::jsonb),
  ('ex22', null, 'hall', 'ein', 'Toblerone', '62', '{"org":"Drei Teams à 4–5, vier markierte Dreiecke (eines bleibt frei). Jedes Kind mit Ball.","offen":"Jedes Kind dribbelt im Dreieck seines Teams. Auf dein Zeichen wechselt das ganze Team in ein freies Dreieck.","ueben":"Nur links, nur rechts, abwechselnd; nur mit Voll-, Innen- oder Aussenrist führen.","wett":"Welches Team ist zuerst vollzählig im freien Dreieck? Oder: Welches Team ist zuerst wieder im Startdreieck, nachdem es alle anderen besucht hat?","coach":["Rundumblick: alle Mitspielenden sehen (S. 42)"],"var":"Dreiecke weiter auseinander bedeutet längere Wege.","d":{"s":"hall","items":[["c",10,8],["c",34,8],["c",22,28],["c",66,8],["c",90,8],["c",78,28],["c",10,56],["c",34,56],["c",22,36],["c",66,56],["c",90,56],["c",78,36],["A",18,14,1],["A",26,16,1],["B",74,14,1],["B",82,16,1],["N",18,50,1],["N",26,48,1],["drib",28,48,66,50],["txt",78,50,"frei"]]}}'::jsonb),
  ('ex23', null, 'hall', 'sp', 'Kleinfeldspiel 3:3 – In die Endzone', '81 · 65', '{"org":"Halle quer in zwei Felder, an beiden Enden eine Endzone (3–4 m). 3:3 und 4:4.","offen":"Einen Punkt erhält, wer in die Endzone gelangt und den Ball dort stoppen kann.","ueben":"Mutig in die Endzone dribbeln, freilaufen, anspielbar sein (in die Sonne) und passen; Blume öffnen und schliessen.","wett":"Welches Team schafft es von Endzone zu Endzone ohne Ballverlust?","own":"Eigener Tipp: In die Tiefe starten, wenn der Passgeber den Kopf hebt.","coach":["Mit dem Ball als Sonne aus dem Schatten heraustreten (S. 42)"],"var":"Schmalere Endzone macht es schwerer.","d":{"s":"hall","items":[["zone",0,0,12,64,"Endzone"],["zone",88,0,12,64,"Endzone"],["A",24,22],["A",34,46],["A",62,30,1],["A",70,10],["B",78,26],["B",70,46],["B",50,20],["run",70,10,93,20],["pass",64,29,92,22]]}}'::jsonb),
  ('ex24', null, 'hall', 'le', 'Drei Aussenspieler/innen', '71', '{"org":"Feld ca. 30×20 m mit zwei Toren. 3:3 im Feld, pro Team drei Aussenspieler/innen an den Linien, die übrigen zwei Kinder sind Torhüter/innen.","offen":"Die Teams können ihre Aussenspieler/innen jederzeit anspielen. Spielen diese direkt zurück, bleiben sie aussen. Nehmen sie den Ball an und laufen ins Feld, übernimmt der Passgeber ihre Rolle.","ueben":"Die Satelliten in der Breite und der Tiefe einbeziehen; als Aussenspieler/in den Ball kontrolliert ins Feld mitnehmen und entschlossen abschliessen.","wett":"Welches Team erzielt in 3 Minuten mehr Tore?","coach":["Blume öffnen bei eigenem Ballbesitz (S. 70)","Vor dem Pass ein Foto vom Ziel machen"],"var":"Aussenspieler/innen nur mit Direktspiel ist schwerer, mit zwei Kontakten leichter.","d":{"s":"hall","items":[["G","L"],["G","R"],["A",3,32],["B",97,32],["A",24,0],["A",74,0],["A",50,64],["B",24,64],["B",74,64],["B",50,0],["A",44,30,1],["A",60,40],["A",34,46],["B",56,22],["B",68,34],["B",40,40],["pass",46,28,26,2],["drib",26,3,62,18],["shot",64,20,98,29]]}}'::jsonb),
  ('ex25', null, 'hall', 'vi', 'Tannenbaum-Fangis', '80', '{"org":"Halbe Halle, zwei Fänger/innen.","offen":"Wer berührt wird, steht wie eine Tanne (Arme ausgestreckt, breitbeinig). Befreit wird, wer von einem anderen Kind zwischen den Beinen durchkrochen wird.","ueben":"Als Fänger/innen gemeinsam eine Strategie festlegen.","wett":"Schaffen es die Fänger/innen, alle zu fangen? Wer befreit fünf Tannen?","coach":["Rennen, Ausweichen, Kriechen: vielseitig bewegen"],"var":"Drei Fänger/innen machen es schwerer.","d":{"s":"hall","items":[["area",10,6,80,52],["B",40,24],["B",64,40],["A",30,40],["A",70,18],["A",52,30],["A",22,18],["txt",30,48,"Tanne"],["run",40,24,48,28],["run",22,18,28,36]]}}'::jsonb),
  ('ex26', null, 'hall', 'aus', 'Bowling', '82', '{"org":"Paare mit vier Markierkegeln und einem Ball, fünf Meter Abstand.","ablauf":"Abwechselnd versucht ein Kind, die Kegel mit einem Pass umzuwerfen. Wie viele Versuche braucht das Paar für alle vier? Danach Schlusswort und gegenseitige Verabschiedung.","coach":["Fragen an die Kinder stellen (siehe oben)"],"var":"","d":{"s":"hall","items":[["c",70,14],["c",72,18],["c",70,22],["c",72,26],["A",40,20,1],["A",84,20],["pass",42,20,68,19],["c",70,40],["c",72,44],["c",70,48],["c",72,52],["B",40,46,1],["B",84,46],["pass",42,46,68,45]]}}'::jsonb)
on conflict (id) do update set data = excluded.data, name = excluded.name, page = excluded.page;

